//! Unit tests of `crate::eth::network` (P0.3): a child module of it (`#[path]` in
//! `src/eth/network.rs`), so private items are in scope.

use super::*;
use crate::eth::{
    duty::Duty,
    types::{AttestationData, BeaconBlockHeader, Checkpoint, DepositMessage, VoluntaryExit},
    web3signer::parse_request,
};
use std::path::Path;

/// The chain of the Lighthouse fixtures (generated by Lighthouse v8.3.2 with mainnet's fork
/// schedule and this genesis validators root).
const FIXTURE_CHAIN: Root =
    hex32("04700007fabc8282644aed6d1c7c9e21d38a03a0c4ba193f3afe428824b3a673");

/// Mainnet's schedule and clock with the fixtures' genesis validators root.
const FIXTURES: Network = Network {
    genesis_validators_root: FIXTURE_CHAIN,
    ..Network::MAINNET
};

fn version(value: u32) -> Version {
    value.to_be_bytes()
}

fn lighthouse(name: &str) -> DutyRequest {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/lighthouse")
        .join(name);
    let parsed = parse_request(&std::fs::read(path).unwrap()).unwrap();
    DutyRequest {
        validator: [7; 48],
        fork: parsed.fork,
        duty: parsed.duty,
    }
}

fn block(slot: u64) -> Duty {
    Duty::BlockProposal(BeaconBlockHeader {
        slot,
        proposer_index: 1,
        parent_root: [1; 32],
        state_root: [2; 32],
        body_root: [3; 32],
    })
}

fn attestation(target: u64) -> Duty {
    Duty::Attestation(AttestationData {
        slot: target * 32,
        index: 0,
        beacon_block_root: [4; 32],
        source: Checkpoint {
            epoch: target - 1,
            root: [5; 32],
        },
        target: Checkpoint {
            epoch: target,
            root: [4; 32],
        },
    })
}

fn exit(epoch: u64) -> Duty {
    Duty::VoluntaryExit(VoluntaryExit {
        epoch,
        validator_index: 12,
    })
}

fn deposit() -> Duty {
    Duty::Deposit(DepositMessage {
        pubkey: [7; 48],
        withdrawal_credentials: [1; 32],
        amount: 32_000_000_000,
    })
}

/// `duty` with `fork` on `network`'s chain.
fn request(network: &Network, duty: Duty, fork: Fork) -> DutyRequest {
    DutyRequest {
        validator: [7; 48],
        fork: ForkInfo {
            fork,
            genesis_validators_root: network.genesis_validators_root,
        },
        duty,
    }
}

fn fork(previous: u32, current: u32, epoch: u64) -> Fork {
    Fork {
        previous_version: version(previous),
        current_version: version(current),
        epoch,
    }
}

/// The pinned schedules are the specifications' (`consensus-specs` `configs/mainnet.yaml`,
/// `eth-clients/hoodi` `metadata/config.yaml`), and complete.
#[test]
fn the_pinned_schedules() {
    for network in [Network::MAINNET, Network::HOODI] {
        assert_eq!(network.validate(), Ok(()));
        assert_eq!(network.forks.len(), ForkName::ALL.len());
    }
    let schedule = |network: &Network| {
        network
            .forks
            .iter()
            .map(|fork| {
                (
                    fork.name.name(),
                    u32::from_be_bytes(fork.version),
                    fork.epoch,
                )
            })
            .collect::<Vec<_>>()
    };
    assert_eq!(
        schedule(&Network::MAINNET),
        [
            ("phase0", 0x0000_0000, 0),
            ("altair", 0x0100_0000, 74_240),
            ("bellatrix", 0x0200_0000, 144_896),
            ("capella", 0x0300_0000, 194_048),
            ("deneb", 0x0400_0000, 269_568),
            ("electra", 0x0500_0000, 364_032),
            ("fulu", 0x0600_0000, 411_392),
        ]
    );
    assert_eq!(
        schedule(&Network::HOODI),
        [
            ("phase0", 0x1000_0910, 0),
            ("altair", 0x2000_0910, 0),
            ("bellatrix", 0x3000_0910, 0),
            ("capella", 0x4000_0910, 0),
            ("deneb", 0x5000_0910, 0),
            ("electra", 0x6000_0910, 2_048),
            ("fulu", 0x7000_0910, 50_688),
        ]
    );
    assert_eq!(Network::named("mainnet"), Some(Network::MAINNET));
    assert_eq!(Network::named("hoodi"), Some(Network::HOODI));
    assert_eq!(Network::named("sepolia"), None);
    assert_ne!(Network::MAINNET.identity(), Network::HOODI.identity());
    assert_ne!(FIXTURES.identity(), Network::MAINNET.identity());
    assert_eq!(
        FIXTURES.schedule_digest(),
        Network::MAINNET.schedule_digest()
    );
    // The JSON form reads back as the same network.
    let json = Network::HOODI.to_json();
    assert_eq!(Network::from_json(&json), Ok(Network::HOODI));
    assert_eq!(
        json.identity,
        format!("0x{}", hex::encode(Network::HOODI.identity()))
    );
}

/// P0.3 test 1 and 18: every request Lighthouse v8.3.2 sends on mainnet's schedule passes, from
/// Bellatrix to Fulu (its exits with Capella's version, EIP-7044).
#[test]
fn lighthouse_requests_follow_mainnet() {
    for name in [
        "block_v2_bellatrix.json",
        "block_v2_capella.json",
        "block_v2_deneb.json",
        "block_v2_electra.json",
        "block_v2_fulu.json",
        "attestation.json",
        "randao_reveal.json",
        "aggregation_slot.json",
        "aggregate_and_proof_phase0.json",
        "aggregate_and_proof_electra.json",
        "sync_committee_message.json",
        "sync_committee_selection_proof.json",
        "contribution_and_proof.json",
        "voluntary_exit.json",
    ] {
        let request = lighthouse(name);
        assert_eq!(FIXTURES.check(&request), Ok(()), "{name}");
        // The fork_info the network gives the duty is the one Lighthouse sent.
        assert_eq!(FIXTURES.fork_info(&request.duty), request.fork, "{name}");
    }
}

/// P0.3 test 2: Hoodi, whose first forks share epoch 0; its fork_info is the latest fork in
/// effect at the duty's epoch.
#[test]
fn hoodi_requests() {
    let hoodi = Network::HOODI;
    for (epoch, expected) in [
        (0, fork(0x5000_0910, 0x5000_0910, 0)),
        (2_047, fork(0x4000_0910, 0x5000_0910, 0)),
        (2_048, fork(0x5000_0910, 0x6000_0910, 2_048)),
        (50_687, fork(0x5000_0910, 0x6000_0910, 2_048)),
        (50_688, fork(0x6000_0910, 0x7000_0910, 50_688)),
    ] {
        // Epoch 0 is Deneb's: Altair to Deneb all start there.
        let expected = if epoch == 0 {
            fork(0x4000_0910, 0x5000_0910, 0)
        } else {
            expected
        };
        assert_eq!(hoodi.fork_at(epoch), expected, "epoch {epoch}");
        let duty = attestation(epoch.max(1));
        let info = hoodi.fork_info(&duty);
        assert_eq!(hoodi.check(&request(&hoodi, duty, info.fork)), Ok(()));
    }
    // Exits: Capella's version from Deneb (epoch 0) on.
    assert_eq!(
        hoodi.fork_info(&exit(9)).fork,
        fork(0x4000_0910, 0x4000_0910, 9)
    );
    // A deposit: Hoodi's genesis fork version, no root.
    let deposit_info = hoodi.fork_info(&deposit());
    assert_eq!(deposit_info.fork, fork(0x1000_0910, 0x1000_0910, 0));
    assert_eq!(deposit_info.genesis_validators_root, [0; 32]);
}

/// The beacon state's form, which Lighthouse sends from the state: on a network whose genesis
/// is at a later fork (Hoodi before Electra, a devnet at Fulu from genesis) and after a
/// blob-parameter-only fork, the version twice at an epoch where it is in effect. Found on the
/// devnet (run `20261107T072938Z`): every duty was refused before this form was accepted.
#[test]
fn the_beacon_states_own_fork_form() {
    // Hoodi before Electra: Deneb from genesis.
    let hoodi = Network::HOODI;
    let deneb = fork(0x5000_0910, 0x5000_0910, 0);
    assert_eq!(
        hoodi.check(&request(&hoodi, attestation(100), deneb)),
        Ok(())
    );
    // ... but not once Electra is in effect.
    assert!(matches!(
        hoodi.check(&request(&hoodi, attestation(3_000), deneb)),
        Err(WrongFork::WrongVersion { .. })
    ));
    // A devnet at Fulu from genesis: Fulu twice at epoch 0; Deneb (never in effect) refused.
    let devnet = Network {
        genesis_validators_root: [3; 32],
        forks: Vec::leak(
            Network::parse_schedule(
                "phase0=0x10000038@0,altair=0x20000038@0,bellatrix=0x30000038@0,\
                 capella=0x40000038@0,deneb=0x50000038@0,electra=0x60000038@0,fulu=0x70000038@0",
            )
            .unwrap(),
        ),
        ..Network::MAINNET
    };
    assert_eq!(
        devnet.check(&request(
            &devnet,
            block(101),
            fork(0x7000_0038, 0x7000_0038, 0)
        )),
        Ok(())
    );
    assert!(matches!(
        devnet.check(&request(
            &devnet,
            block(101),
            fork(0x5000_0038, 0x5000_0038, 0)
        )),
        Err(WrongFork::NotAFork { .. })
    ));
    // Mainnet after a blob-parameter-only fork: Fulu twice at an epoch after Fulu's.
    let mainnet = Network::MAINNET;
    let bpo = fork(0x0600_0000, 0x0600_0000, 419_072);
    assert_eq!(
        mainnet.check(&request(&mainnet, attestation(420_000), bpo)),
        Ok(())
    );
    // Fulu twice at an epoch before Fulu: not a fork of the schedule.
    assert!(matches!(
        mainnet.check(&request(
            &mainnet,
            attestation(420_000),
            fork(0x0600_0000, 0x0600_0000, 400_000)
        )),
        Err(WrongFork::NotAFork { .. })
    ));
}

/// P0.3 tests 3 to 6 and 10: another chain, another version, another fork epoch, another
/// network's forks, a fork this build does not know.
#[test]
fn a_fork_info_that_is_not_the_networks_is_refused() {
    let mainnet = Network::MAINNET;
    let fulu = fork(0x0500_0000, 0x0600_0000, 411_392);
    let duty = attestation(411_400);
    assert_eq!(
        mainnet.check(&request(&mainnet, duty.clone(), fulu)),
        Ok(())
    );

    // 3: another genesis validators root.
    let mut other_chain = request(&mainnet, duty.clone(), fulu);
    other_chain.fork.genesis_validators_root = [0x42; 32];
    assert_eq!(mainnet.check(&other_chain), Err(WrongFork::OtherChain));
    // 4: Electra's fork for a Fulu duty (its version is not the schedule's there).
    assert!(matches!(
        mainnet.check(&request(
            &mainnet,
            duty.clone(),
            fork(0x0400_0000, 0x0500_0000, 364_032)
        )),
        Err(WrongFork::WrongVersion { epoch: 411_400, .. })
    ));
    // 5: Fulu's versions at another epoch, or with another previous version.
    for wrong in [
        fork(0x0500_0000, 0x0600_0000, 411_391),
        fork(0x0500_0000, 0x0600_0000, 0),
        fork(0x0400_0000, 0x0600_0000, 411_392),
        fork(0x0600_0000, 0x0600_0000, 411_391),
    ] {
        assert!(
            matches!(
                mainnet.check(&request(&mainnet, duty.clone(), wrong)),
                Err(WrongFork::NotAFork { .. })
            ),
            "{wrong:?}"
        );
    }
    // 6: Hoodi's Fulu on mainnet's chain.
    assert!(matches!(
        mainnet.check(&request(
            &mainnet,
            duty.clone(),
            fork(0x6000_0910, 0x7000_0910, 50_688)
        )),
        Err(WrongFork::UnknownVersion { .. })
    ));
    // 10: Gloas, not in the schedule (not scheduled on mainnet, unknown to this build).
    assert!(matches!(
        mainnet.check(&request(
            &mainnet,
            duty,
            fork(0x0600_0000, 0x0700_0000, 500_000)
        )),
        Err(WrongFork::UnknownVersion { .. })
    ));
}

/// P0.3 tests 7 to 9: block proposals just before Fulu, at its first slot and after. Before, the
/// fork of either side gives Electra's version; from the first slot on, only Fulu's fork passes.
#[test]
fn around_a_fork_transition() {
    let mainnet = Network::MAINNET;
    let first = 411_392 * 32;
    let electra = fork(0x0400_0000, 0x0500_0000, 364_032);
    let fulu = fork(0x0500_0000, 0x0600_0000, 411_392);
    let check = |slot, fork| mainnet.check(&request(&mainnet, block(slot), fork));
    // 7: the last slot of Electra: its own fork, or Fulu's (whose previous version it uses).
    assert_eq!(check(first - 1, electra), Ok(()));
    assert_eq!(check(first - 1, fulu), Ok(()));
    assert_eq!(mainnet.fork_info(&block(first - 1)).fork, electra);
    // 8: Fulu's first slot: Fulu's fork only.
    assert_eq!(check(first, fulu), Ok(()));
    assert!(matches!(
        check(first, electra),
        Err(WrongFork::WrongVersion { epoch: 411_392, .. })
    ));
    // 9: after it, the same.
    assert_eq!(check(first + 33, fulu), Ok(()));
    assert!(check(first + 33, electra).is_err());
    // A Fulu fork for an Electra-era attestation that is older than Fulu's previous version:
    // Deneb's epoch uses Deneb's version, which Fulu's fork cannot give.
    assert!(matches!(
        mainnet.check(&request(&mainnet, attestation(300_000), fulu)),
        Err(WrongFork::WrongVersion { epoch: 300_000, .. })
    ));
}

/// Exits (EIP-7044) and deposits have their own domains.
#[test]
fn exits_and_deposits() {
    let mainnet = Network::MAINNET;
    let capella = fork(0x0300_0000, 0x0300_0000, 400_000);
    // From Deneb on: Capella's version, the exit's epoch; nothing else.
    assert_eq!(
        mainnet.check(&request(&mainnet, exit(400_000), capella)),
        Ok(())
    );
    for wrong in [
        fork(0x0500_0000, 0x0600_0000, 411_392),
        fork(0x0300_0000, 0x0300_0000, 399_999),
        fork(0x0200_0000, 0x0300_0000, 194_048),
    ] {
        assert!(
            matches!(
                mainnet.check(&request(&mainnet, exit(400_000), wrong)),
                Err(WrongFork::Exit { epoch: 400_000, .. })
            ),
            "{wrong:?}"
        );
    }
    // Before Deneb: the fork in effect at the exit's epoch.
    let bellatrix = fork(0x0100_0000, 0x0200_0000, 144_896);
    assert_eq!(
        mainnet.check(&request(&mainnet, exit(150_000), bellatrix)),
        Ok(())
    );
    assert!(
        mainnet
            .check(&request(&mainnet, exit(150_000), capella))
            .is_err()
    );

    // A deposit: the genesis fork version, epoch 0, no root.
    let deposit_request = |version: u32, root: Root| DutyRequest {
        validator: [7; 48],
        fork: ForkInfo {
            fork: fork(version, version, 0),
            genesis_validators_root: root,
        },
        duty: deposit(),
    };
    assert_eq!(mainnet.check(&deposit_request(0, [0; 32])), Ok(()));
    for wrong in [
        deposit_request(0x1000_0910, [0; 32]),
        deposit_request(0, mainnet.genesis_validators_root),
        deposit_request(0x0100_0000, [0; 32]),
    ] {
        assert!(matches!(
            mainnet.check(&wrong),
            Err(WrongFork::Deposit { .. })
        ));
    }
}

/// P0.3 test 11: another network's schedule is given in full, in order, or refused.
#[test]
fn a_custom_schedule_is_complete() {
    let devnet = |schedule: &str| -> Result<Network, String> {
        let network = Network {
            genesis_time: 1_700_000_000,
            seconds_per_slot: 6,
            slots_per_epoch: 32,
            genesis_validators_root: [3; 32],
            forks: Vec::leak(Network::parse_schedule(schedule)?),
        };
        network.validate().map(|()| network)
    };
    let network = devnet(
        "phase0=0x10000038@0,altair=0x20000038@0,bellatrix=0x30000038@0,capella=0x40000038@0,\
         deneb=0x50000038@0,electra=0x60000038@0,fulu=0x70000038@10",
    )
    .unwrap();
    assert_eq!(network.version_at(9), version(0x6000_0038));
    assert_eq!(network.version_at(10), version(0x7000_0038));
    // A schedule may end before the last fork this build knows.
    assert!(devnet("phase0=0x10000038@0,altair=0x20000038@5").is_ok());
    for wrong in [
        "",
        "altair=0x20000038@0",
        "phase0=0x10000038@3",
        "phase0=0x10000038@0,bellatrix=0x30000038@0",
        "phase0=0x10000038@0,altair=0x20000038@9,bellatrix=0x30000038@8",
        "phase0=0x10000038@0,altair=0x10000038@0",
        "phase0=0x10000038@0,gloas=0x20000038@0",
        "phase0=0x100038@0",
        "phase0:0x10000038:0",
    ] {
        assert!(devnet(wrong).is_err(), "{wrong:?}");
    }
    // The minimal preset is not supported.
    let minimal = Network {
        slots_per_epoch: 8,
        ..Network::MAINNET
    };
    assert!(minimal.validate().is_err());
}
